        MouseDown+=(_,e)=>{Focus();var p=e.GetPosition(this);Begin(new((float)p.X,(float)p.Y),e.ChangedButton==MouseButton.Middle||Keyboard.IsKeyDown(Key.Space),e.ClickCount>1);};MouseMove+=(_,e)=>{var p=e.GetPosition(this);Move(new((float)p.X,(float)p.Y));};MouseUp+=(_,_)=>End();LostMouseCapture+=(_,_)=>{if(_drag>=0||_pan)CancelGesture();};MouseWheel+=(_,e)=>{var p=e.GetPosition(this);Viewport.ZoomAt(e.Delta>0?1.25:.8,new((float)p.X,(float)p.Y));InvalidateVisual();};
